def e(s): return html.escape(str(s), quote=True)

def event_image(ev):
    if ev['genre'] in ('festival',):
        return 'assets/medina-festival-wide.jpg'
    if ev['genre'] in ('theatre','comedy'):
        return 'assets/theatre-wide.jpg'
    if ev['genre'] == 'jazz':
        return 'assets/medina-festival-wide.jpg'
    return 'assets/concert-wide.jpg'

def event_card(ev):
    photo=event_image(ev)
    return f'''<article class="event-card" data-event-card data-city="{e(ev['city'])}">
      <a href="{ev['slug']}" class="event-art {ev['genre']}" aria-label="Voir {e(ev['title'])}">
        <img class="event-photo" src="{photo}" alt="Ambiance {e(ev['kind'].lower())} en Tunisie" loading="lazy">
        <span class="event-date"><b>{ev['day']}</b>{ev['month']}</span>
        <div class="event-art-content"><span class="tag">{ev['kind']}</span><strong>{e(ev['title'])}</strong></div>
      </a>
      <div class="event-body"><div class="event-meta"><span>📅 {ev['date']}</span><span>📍 {ev['city']}</span></div>
        <h3><a href="{ev['slug']}">{e(ev['title'])}</a></h3><p>{e(ev['desc'])}</p>
        <div class="event-bottom"><span class="price">Dès {ev['price']} TND<small>Prix indicatif de démonstration</small></span><a class="btn btn-outline btn-small" href="{ev['slug']}">Voir l’événement →</a></div>
      </div></article>'''

