def shell(title,desc,body,active='',canonical=None):
    c=canonical or ''
    return f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="robots" content="index,follow"><link rel="canonical" href="https://reservi.tn/{c}"><meta name="theme-color" content="#101c36"><meta property="og:site_name" content="Reservi.tn"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:image" content="https://reservi.tn/assets/concert-wide.jpg"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"></head><body>{header(active)}{body}{footer()}</body></html>'''

def page_hero(title,desc,crumb='Accueil'):
    return f'''<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="index.html">Accueil</a>　›　{e(crumb)}</div><h1>{title}</h1><p>{desc}</p></div></section>'''

