legal_pages={
 'mentions-legales.html':('Mentions légales','Informations relatives à l’éditeur, à la publication et à l’hébergement du site Reservi.tn.', '''<h2>Éditeur du site</h2><p>Nom ou raison sociale : à compléter par le porteur réel du projet.<br>Adresse : à compléter.<br>Identifiant légal et coordonnées : à compléter selon la situation juridique de l’éditeur.</p><h2>Responsable de publication</h2><p>Nom du responsable de publication : à compléter avant toute mise en ligne publique.</p><h2>Hébergement</h2><p>Nom et coordonnées de l’hébergeur : à renseigner avec les informations du prestataire réellement utilisé.</p><h2>Propriété intellectuelle</h2><p>Les textes, éléments graphiques, logos et contenus du site doivent être utilisés avec les droits et autorisations nécessaires. Les éléments de cette maquette sont fournis pour le projet pédagogique.</p>'''),
 'confidentialite.html':('Politique de confidentialité','Découvrez les principes de collecte, d’utilisation et de protection des données personnelles sur Reservi.tn.', '''<h2>Données susceptibles d’être collectées</h2><p>Dans une version opérationnelle, la plateforme pourrait traiter les informations nécessaires à la gestion d’un compte, d’une réservation, d’une demande de contact ou d’une assistance.</p><h2>Finalités</h2><p>Les données devront être utilisées uniquement pour les finalités expliquées aux utilisateurs : traitement des demandes, gestion des réservations, service client et obligations légales applicables.</p><h2>Conservation et sécurité</h2><p>Les durées de conservation, les mesures de sécurité et les prestataires ayant accès aux données devront être documentés avant la mise en production.</p><h2>Vos droits</h2><p>Les modalités d’exercice des droits des personnes concernées et les coordonnées du responsable de traitement doivent être précisées conformément aux règles applicables en Tunisie.</p>'''),
 'cgv.html':('Conditions générales de vente','Conditions indicatives à adapter avant toute vente réelle de billets sur Reservi.tn.', '''<h2>Objet</h2><p>Les présentes conditions ont vocation à encadrer la consultation des événements et l’achat de billets via la plateforme Reservi.tn.</p><h2>Informations sur l’événement</h2><p>Chaque fiche événement devra préciser l’organisateur, la date, l’horaire, le lieu, les tarifs, les frais éventuels et les conditions particulières d’accès.</p><h2>Commande et paiement</h2><p>La commande ne sera considérée comme confirmée qu’après validation selon le parcours de paiement réellement intégré. Les moyens de paiement et les étapes de confirmation devront être décrits de manière transparente.</p><h2>Responsabilité de l’organisateur</h2><p>Les responsabilités relatives à la tenue, à la modification ou à l’annulation d’un événement doivent être clairement réparties et communiquées.</p><p class="notice">Ce texte est un canevas de projet et ne constitue pas des conditions générales prêtes à être utilisées pour une vente réelle. Faites-les vérifier avant lancement.</p>'''),
 'remboursement.html':('Politique de remboursement','Consultez les principes à préciser concernant les annulations, les reports et les remboursements.', '''<h2>Annulation ou report d’un événement</h2><p>Les modalités applicables en cas d’annulation ou de report doivent être indiquées sur la fiche de l’événement et communiquées aux acheteurs.</p><h2>Demande de remboursement</h2><p>La procédure devra préciser le canal de contact, les justificatifs éventuels, les délais de traitement et le mode de remboursement applicable.</p><h2>Cas particuliers</h2><p>Les conditions peuvent varier selon l’organisateur et la nature de l’événement. Les règles applicables doivent être clairement portées à la connaissance du client avant l’achat.</p><p class="notice">Politique de démonstration : elle doit être complétée et validée avec les organisateurs et les obligations juridiques applicables avant toute vente réelle.</p>''')
}
